window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-82e6caeeb0432704"]={"versions": [{"id": "FIG-82e6caeeb0432704", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des pollingbasierten Ablaufs der Sende-Bestätigung (Transmit Confirmation Polling Driven) innerhalb der AUTOSAR-Basissoftwarearchitektur (Classic Platform, Communication Stack). Der Ablauf zeigt die Interaktion zwischen Betriebssystem-/Scheduler-Ebene, CAN-Treiber, CAN-Interface und oberen Kommunikationsschichten bei zyklischer Abfrage des Sende-Status.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW Scheduler</strong>: Akteur/Entität zur zyklischen Aktivierung von periodischen Basissoftware-Tasks.\n</li><li><strong>CanIf User</strong>: Generische obere Kommunikationsschicht bzw. Nutzer des CAN-Interfaces (z. B. PduR, CanNm, CanTp).\n</li><li><strong>«module» CanIf</strong>: AUTOSAR CAN-Interface-Modul zur Abstraktion der darunterliegenden Hardwaretreiber.\n</li><li><strong>«module» Can</strong>: AUTOSAR CAN-Treiber (MCAL-Schicht), gekennzeichnet mit Dekompositionssymbol.\n</li><li><strong>«Peripheral» CanController</strong>: CAN-Hardware-Controller (Peripherie).\n</li><li><strong>Schnittstellen &amp; Operationen</strong>:\n<ul class=\"fig-list\"><li><code>Can_MainFunction_Write()</code>: Zyklische Funktion des CAN-Treibers zur Bearbeitung von Sendeaufträgen und Polling des Sendestatus.\n</li><li><code>Check for pending TX confirmations()</code>: Treiberinterner Hardwarezugriff zur Prüfung ausstehender Sende-Bestätigungen am Controller.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Bestätigungs-Callback vom CAN-Treiber an das CAN-Interface mit Übergabe der PDU-Kennung.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code>: Konfigurierbarer Bestätigungs-Callback vom CAN-Interface an das darüberliegende Nutzer-Modul mit Angabe der PDU-ID und des Übertragungsergebnisses.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schleifenkontext (<code>loop Cyclic Task of Interface</code>)</strong>:\n<ul class=\"fig-list\"><li>Der BSW Scheduler ruft periodisch <code>Can_MainFunction_Write()</code> auf dem <code>Can</code>-Modul auf.\n</li><li>Das <code>Can</code>-Modul prüft per synchronem Zugriff <code>Check for pending TX confirmations()</code> den Hardwarezustand am <code>CanController</code>.\n</li></ul>\n</li><li><strong>Bedingte Verzweigung (<code>alt Pending Tx confirmation</code>)</strong>:\n<ul class=\"fig-list\"><li><strong>Zweig <code>[Tx confirmation is pending ]</code></strong>:\n<ul class=\"fig-list\"><li>Das <code>Can</code>-Modul ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Das <code>CanIf</code> leitet das Bestätigungsereignis synchron über <code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code> an die obere Schicht (<code>CanIf User</code>) weiter.\n</li><li>Nach Rückkehr (<code>&lt;User_TxConfirmation&gt;()</code>) kehrt auch <code>CanIf_TxConfirmation()</code> zum <code>Can</code>-Modul zurück.\n</li></ul>\n</li><li><strong>Zweig <code>[No Tx confirmation is pending]</code></strong>:\n<ul class=\"fig-list\"><li>Es finden keine weiteren Aufrufe statt.\n</li></ul>\n</li></ul>\n</li><li>Nach Abschluss der Verzweigung kehrt <code>Can_MainFunction_Write()</code> zum <code>BSW Scheduler</code> zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die Entkopplung von Sendeabschluss und Bestätigungsverarbeitung im Polling-Modus: Sende-Bestätigungen werden nicht asynchron im Kontext einer Interrupt Service Routine (ISR) ausgelöst, sondern deterministisch im Kontext des Task-Schedulers über <code>Can_MainFunction_Write()</code>.\n</li><li>Das CAN-Interface verarbeitet <code>CanIf_TxConfirmation()</code> im Aufrufkontext des Treibers und benachrichtigt obere Schichten unmittelbar synchron.\n</li><li>Obere Schichten müssen darauf ausgelegt sein, dass der Callback <code>&lt;User_TxConfirmation&gt;</code> im Kontext der zyklischen Schreiber-Task (<code>Can_MainFunction_Write</code>) aufgerufen wird.\n</li></ul>"}, {"id": "FIG-f09e29b939da69ab", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des pollingbasierten Ablaufs der Sende-Bestätigung (Transmit Confirmation Polling Driven) innerhalb der AUTOSAR-Basissoftwarearchitektur (Classic Platform, Communication Stack). Der Ablauf zeigt die Interaktion zwischen Betriebssystem-/Scheduler-Ebene, CAN-Treiber, CAN-Interface und oberen Kommunikationsschichten bei zyklischer Abfrage des Sende-Status.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW Scheduler</strong>: Akteur/Entität zur zyklischen Aktivierung von periodischen Basissoftware-Tasks.\n</li><li><strong>CanIf User</strong>: Generische obere Kommunikationsschicht bzw. Nutzer des CAN-Interfaces (z. B. PduR, CanNm, CanTp).\n</li><li><strong>«module» CanIf</strong>: AUTOSAR CAN-Interface-Modul zur Abstraktion der darunterliegenden Hardwaretreiber.\n</li><li><strong>«module» Can</strong>: AUTOSAR CAN-Treiber (MCAL-Schicht), gekennzeichnet mit Dekompositionssymbol.\n</li><li><strong>«Peripheral» CanController</strong>: CAN-Hardware-Controller (Peripherie).\n</li><li><strong>Schnittstellen &amp; Operationen</strong>:\n<ul class=\"fig-list\"><li><code>Can_MainFunction_Write()</code>: Zyklische Funktion des CAN-Treibers zur Bearbeitung von Sendeaufträgen und Polling des Sendestatus.\n</li><li><code>Check for pending TX confirmations()</code>: Treiberinterner Hardwarezugriff zur Prüfung ausstehender Sende-Bestätigungen am Controller.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Bestätigungs-Callback vom CAN-Treiber an das CAN-Interface mit Übergabe der PDU-Kennung.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code>: Konfigurierbarer Bestätigungs-Callback vom CAN-Interface an das darüberliegende Nutzer-Modul mit Angabe der PDU-ID und des Übertragungsergebnisses.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schleifenkontext (<code>loop Cyclic Task of Interface</code>)</strong>:\n<ul class=\"fig-list\"><li>Der BSW Scheduler ruft periodisch <code>Can_MainFunction_Write()</code> auf dem <code>Can</code>-Modul auf.\n</li><li>Das <code>Can</code>-Modul prüft per synchronem Zugriff <code>Check for pending TX confirmations()</code> den Hardwarezustand am <code>CanController</code>.\n</li></ul>\n</li><li><strong>Bedingte Verzweigung (<code>alt Pending Tx confirmation</code>)</strong>:\n<ul class=\"fig-list\"><li><strong>Zweig <code>[Tx confirmation is pending ]</code></strong>:\n<ul class=\"fig-list\"><li>Das <code>Can</code>-Modul ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Das <code>CanIf</code> leitet das Bestätigungsereignis synchron über <code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code> an die obere Schicht (<code>CanIf User</code>) weiter.\n</li><li>Nach Rückkehr (<code>&lt;User_TxConfirmation&gt;()</code>) kehrt auch <code>CanIf_TxConfirmation()</code> zum <code>Can</code>-Modul zurück.\n</li></ul>\n</li><li><strong>Zweig <code>[No Tx confirmation is pending]</code></strong>:\n<ul class=\"fig-list\"><li>Es finden keine weiteren Aufrufe statt.\n</li></ul>\n</li></ul>\n</li><li>Nach Abschluss der Verzweigung kehrt <code>Can_MainFunction_Write()</code> zum <code>BSW Scheduler</code> zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die Entkopplung von Sendeabschluss und Bestätigungsverarbeitung im Polling-Modus: Sende-Bestätigungen werden nicht asynchron im Kontext einer Interrupt Service Routine (ISR) ausgelöst, sondern deterministisch im Kontext des Task-Schedulers über <code>Can_MainFunction_Write()</code>.\n</li><li>Das CAN-Interface verarbeitet <code>CanIf_TxConfirmation()</code> im Aufrufkontext des Treibers und benachrichtigt obere Schichten unmittelbar synchron.\n</li><li>Obere Schichten müssen darauf ausgelegt sein, dass der Callback <code>&lt;User_TxConfirmation&gt;</code> im Kontext der zyklischen Schreiber-Task (<code>Can_MainFunction_Write</code>) aufgerufen wird.\n</li></ul>"}, {"id": "FIG-0a0e1537f21df4d7", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des pollingbasierten Ablaufs der Sende-Bestätigung (Transmit Confirmation Polling Driven) innerhalb der AUTOSAR-Basissoftwarearchitektur (Classic Platform, Communication Stack). Der Ablauf zeigt die Interaktion zwischen BSW Scheduler, CAN-Treiber, CAN-Interface und dem Large SDU Router (LSduR) bei zyklischer Abfrage des Sende-Status.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW Scheduler</strong>: Akteur/Entität zur zyklischen Aktivierung von periodischen Basissoftware-Tasks.\n</li><li><strong>«module» LSduR</strong>: Large SDU Router als spezifischer oberer BSW-Nutzer des CAN-Interfaces.\n</li><li><strong>«module» CanIf</strong>: AUTOSAR CAN-Interface-Modul zur Abstraktion der darunterliegenden Hardwaretreiber.\n</li><li><strong>«module» Can</strong>: AUTOSAR CAN-Treiber (MCAL-Schicht), gekennzeichnet mit Dekompositionssymbol.\n</li><li><strong>«Peripheral» CanController</strong>: CAN-Hardware-Controller (Peripherie).\n</li><li><strong>Schnittstellen &amp; Operationen</strong>:\n<ul class=\"fig-list\"><li><code>Can_MainFunction_Write()</code>: Zyklische Funktion des CAN-Treibers zur Bearbeitung von Sendeaufträgen und Polling des Sendestatus.\n</li><li><code>Check for pending TX confirmations()</code>: Treiberinterner Hardwarezugriff zur Prüfung ausstehender Sende-Bestätigungen am Controller.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Bestätigungs-Callback vom CAN-Treiber an das CAN-Interface mit Übergabe der PDU-Kennung.\n</li><li><code>LSduR_CanIfTxConfirmation(PduIdType, Std_ReturnType)</code>: Spezifischer Bestätigungs-Callback vom CAN-Interface an das Modul <code>LSduR</code> mit Übergabe der PDU-ID und des Übertragungsergebnisses.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schleifenkontext (<code>loop Cyclic Task of Interface</code>)</strong>:\n<ul class=\"fig-list\"><li>Der BSW Scheduler ruft periodisch <code>Can_MainFunction_Write()</code> auf dem <code>Can</code>-Modul auf.\n</li><li>Das <code>Can</code>-Modul prüft per synchronem Zugriff <code>Check for pending TX confirmations()</code> den Hardwarezustand am <code>CanController</code>.\n</li></ul>\n</li><li><strong>Bedingte Verzweigung (<code>alt Pending Tx confirmation</code>)</strong>:\n<ul class=\"fig-list\"><li><strong>Zweig <code>[Tx confirmation is pending ]</code></strong>:\n<ul class=\"fig-list\"><li>Das <code>Can</code>-Modul ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Das <code>CanIf</code> leitet das Bestätigungsereignis synchron über <code>LSduR_CanIfTxConfirmation(PduIdType, Std_ReturnType)</code> an das Modul <code>LSduR</code> weiter.\n</li><li>Nach Abschluss der Verarbeitung kehrt der Aufruf über <code>CanIf</code> zurück an das <code>Can</code>-Modul (<code>CanIf_TxConfirmation()</code>).\n</li></ul>\n</li><li><strong>Zweig <code>[No Tx confirmation is pending]</code></strong>:\n<ul class=\"fig-list\"><li>Es finden keine weiteren Aufrufe statt.\n</li></ul>\n</li></ul>\n</li><li>Nach Abschluss der Verzweigung kehrt <code>Can_MainFunction_Write()</code> zum <code>BSW Scheduler</code> zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die Entkopplung von Sendeabschluss und Bestätigungsverarbeitung im Polling-Modus: Sende-Bestätigungen werden nicht asynchron im Kontext einer ISR verarbeitet, sondern deterministisch im Kontext des Task-Schedulers über <code>Can_MainFunction_Write()</code>.\n</li><li>Das CAN-Interface leitet die Bestätigung synchron im selben Task-Kontext an das Zielmodul (<code>LSduR</code>) über dessen typisierte Schnittstelle <code>LSduR_CanIfTxConfirmation</code> weiter.\n</li><li>Das Modul <code>LSduR</code> muss darauf ausgelegt sein, die Bestätigung synchron im Kontext der zyklischen Treiber-Task (<code>Can_MainFunction_Write</code>) entgegenzunehmen.\n</li></ul>"}, {"id": "FIG-fce56a9232238e84", "releases": ["R21-11", "R22-11", "R23-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des pollingbasierten Ablaufs der Sende-Bestätigung (Transmit Confirmation Polling Driven) innerhalb der AUTOSAR-Basissoftwarearchitektur (Classic Platform, Communication Stack). Der Ablauf zeigt die Interaktion zwischen Betriebssystem-/Scheduler-Ebene, CAN-Treiber, CAN-Interface und oberen Kommunikationsschichten bei zyklischer Abfrage des Sende-Status.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW Scheduler</strong>: Akteur/Entität zur zyklischen Aktivierung von periodischen Basissoftware-Tasks.\n</li><li><strong>CanIf User</strong>: Generische obere Kommunikationsschicht bzw. Nutzer des CAN-Interfaces (z. B. PduR, CanNm, CanTp).\n</li><li><strong>«module» CanIf</strong>: AUTOSAR CAN-Interface-Modul zur Abstraktion der darunterliegenden Hardwaretreiber.\n</li><li><strong>«module» Can</strong>: AUTOSAR CAN-Treiber (MCAL-Schicht), gekennzeichnet mit Dekompositionssymbol.\n</li><li><strong>«Peripheral» CanController</strong>: CAN-Hardware-Controller (Peripherie).\n</li><li><strong>Schnittstellen &amp; Operationen</strong>:\n<ul class=\"fig-list\"><li><code>Can_MainFunction_Write()</code>: Zyklische Funktion des CAN-Treibers zur Bearbeitung von Sendeaufträgen und Polling des Sendestatus.\n</li><li><code>Check for pending TX confirmations()</code>: Treiberinterner Hardwarezugriff zur Prüfung ausstehender Sende-Bestätigungen am Controller.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Bestätigungs-Callback vom CAN-Treiber an das CAN-Interface mit Übergabe der PDU-Kennung.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code>: Konfigurierbarer Bestätigungs-Callback vom CAN-Interface an das darüberliegende Nutzer-Modul mit Angabe der PDU-ID und des Übertragungsergebnisses.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schleifenkontext (<code>loop Cyclic Task of Interface</code>)</strong>:\n<ul class=\"fig-list\"><li>Der BSW Scheduler ruft periodisch <code>Can_MainFunction_Write()</code> auf dem <code>Can</code>-Modul auf.\n</li><li>Das <code>Can</code>-Modul prüft per synchronem Zugriff <code>Check for pending TX confirmations()</code> den Hardwarezustand am <code>CanController</code>.\n</li></ul>\n</li><li><strong>Bedingte Verzweigung (<code>alt Pending Tx confirmation</code>)</strong>:\n<ul class=\"fig-list\"><li><strong>Zweig <code>[Tx confirmation is pending ]</code></strong>:\n<ul class=\"fig-list\"><li>Das <code>Can</code>-Modul ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Das <code>CanIf</code> leitet das Bestätigungsereignis synchron über <code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code> an die obere Schicht (<code>CanIf User</code>) weiter.\n</li><li>Nach Rückkehr (<code>&lt;User_TxConfirmation&gt;()</code>) kehrt auch <code>CanIf_TxConfirmation()</code> zum <code>Can</code>-Modul zurück.\n</li></ul>\n</li><li><strong>Zweig <code>[No Tx confirmation is pending]</code></strong>:\n<ul class=\"fig-list\"><li>Es finden keine weiteren Aufrufe statt.\n</li></ul>\n</li></ul>\n</li><li>Nach Abschluss der Verzweigung kehrt <code>Can_MainFunction_Write()</code> zum <code>BSW Scheduler</code> zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die Entkopplung von Sendeabschluss und Bestätigungsverarbeitung im Polling-Modus: Sende-Bestätigungen werden nicht asynchron im Kontext einer Interrupt Service Routine (ISR) ausgelöst, sondern deterministisch im Kontext des Task-Schedulers über <code>Can_MainFunction_Write()</code>.\n</li><li>Das CAN-Interface verarbeitet <code>CanIf_TxConfirmation()</code> im Aufrufkontext des Treibers und benachrichtigt obere Schichten unmittelbar synchron.\n</li><li>Obere Schichten müssen darauf ausgelegt sein, dass der Callback <code>&lt;User_TxConfirmation&gt;</code> im Kontext der zyklischen Schreiber-Task (<code>Can_MainFunction_Write</code>) aufgerufen wird.\n</li></ul>"}], "trans": [{"from": "FIG-82e6caeeb0432704", "to": "FIG-f09e29b939da69ab", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f09e29b939da69ab", "to": "FIG-fce56a9232238e84", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fce56a9232238e84", "to": "FIG-0a0e1537f21df4d7", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Lebenslinie / Komponente</strong>: Die generische Komponente <code>CanIf User</code> wurde durch das konkrete BSW-Modul <code>«module» LSduR</code> ersetzt.\n</li><li><strong>Aufruf / Rückmeldung</strong>: Der generische Callback <code>&lt;User_TxConfirmation&gt;(PduIdType, Std_ReturnType)</code> mit Rückkehr <code>&lt;User_TxConfirmation&gt;()</code> wurde durch den modulspezifischen Callback <code>LSduR_CanIfTxConfirmation(PduIdType, Std_ReturnType)</code> ersetzt (ohne explizite Beschriftung auf dem gestrichelten Rückkehrpfeil).\n</li></ul>"}]};
